use crate::RetirementDemand;
use super::*;
fn post(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u64){assert!(p.fits(*bank));assert!(work<=*fuel);bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).unwrap();}
fn close<T:crate::retirement::RetireOwned>(value:T,bank:&mut RetainedCloneGrant,fuel:&mut u64){let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).map_err(|(error,_)|error).unwrap();for _ in 0..100000{if owner.terminal_is_empty(){return}let(step,heap)=crate::allocation_testing::observe_retirement_allocations(||owner.step(RetainedCloneGrant{maximum_items:1,..*bank}).unwrap());let p=step.progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(bank,fuel,p,owner.last_turn_work());}panic!("actual ordered update cleanup exhausted finite turns")}
#[test]fn actual_ordered_update_stages_each_fallible_birth_and_preserves_every_rotation_cancel_prefix(){let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];for case in row["cases"].as_array().unwrap(){for cut in row["cancelPrefixes"].as_array().unwrap().iter().map(|x|Some(x.as_u64().unwrap())).chain([None]){let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let mut map=OrderedMap::<u64>::new();let mut oracle=std::collections::BTreeMap::new();for(member,pair)in case.as_array().unwrap().iter().enumerate(){let selected_cut=if member+1==case.as_array().unwrap().len(){cut}else{None};let name=pair[0].as_str().unwrap().to_owned();let value=pair[1].as_u64().unwrap();let turn=SharedOwner::admit(name.clone(),RetainedCloneGrant{maximum_items:1,..bank}, &mut None);let(key,p)=turn.result.map_err(|(error,_)|error).unwrap();post(&mut bank,&mut fuel,p,turn.work);let turn=SharedOwner::admit(value,RetainedCloneGrant{maximum_items:1,..bank}, &mut None);let(shared,p)=turn.result.map_err(|(error,_)|error).unwrap();post(&mut bank,&mut fuel,p,turn.work);let mut cursor=map.begin_set_shared(key,shared);let mut injected=false;for at in 0..row["maximumTurns"].as_u64().unwrap(){if selected_cut==Some(at)||cursor.is_complete(){break}let demand=RetirementDemand{copy_bytes:cursor.next_copy_byte_demand(),capacity_bytes:cursor.next_capacity_byte_demand().unwrap(),depth:cursor.next_depth_demand(),..Default::default()};for axis in 0..5{let mut grant=RetainedCloneGrant{maximum_items:1,..bank};match axis{0=>grant.maximum_items=0,1 if demand.copy_bytes>0=>grant.maximum_copy_bytes=demand.copy_bytes-1,2 if demand.capacity_bytes>0=>grant.maximum_capacity_bytes=demand.capacity_bytes-1,3 if demand.release_bytes>0=>grant.maximum_release_bytes=demand.release_bytes-1,4 if demand.depth>0=>grant.maximum_depth=demand.depth-1,_=>continue}let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||cursor.advance(grant,fuel));assert_eq!(turn.work,row["deniedWork"].as_u64().unwrap());let p=match turn.result{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()};assert_eq!(p,Default::default());assert_eq!(heap,(0,0));assert_eq!(cursor.next_capacity_byte_demand().unwrap(),demand.capacity_bytes);assert_eq!(cursor.next_depth_demand(),demand.depth);}if !injected&&demand.capacity_bytes>0{let((turn,attempts),heap)=crate::allocation_testing::observe_retirement_allocations(||crate::allocation_testing::refuse_one_allocation_on_this_thread(||cursor.advance(RetainedCloneGrant{maximum_items:1,..bank},fuel)));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,row["nullWork"].as_u64().unwrap());fuel-=turn.work;assert!(turn.result.is_err());assert_eq!(cursor.next_capacity_byte_demand().unwrap(),demand.capacity_bytes);injected=true;}
 let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||cursor.advance(RetainedCloneGrant{maximum_items:1,..bank},fuel));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(&mut bank,&mut fuel,p,turn.work);}
 if cursor.is_complete(){let next=cursor.take_result().unwrap();let previous=std::mem::replace(&mut map,next);close(previous,&mut bank,&mut fuel);oracle.insert(name,value);let actual:std::collections::BTreeMap<String,u64>=map.iter().map(|(key,value)|(key.to_owned(),*value)).collect();assert_eq!(serde_json::to_value(actual).unwrap(),serde_json::to_value(&oracle).unwrap());}cursor.begin_close();close(cursor,&mut bank,&mut fuel);}close(map,&mut bank,&mut fuel);}}}

#[test]fn actual_controlled_insert_keeps_its_declared_operation_after_value_moves_to_entry(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&law["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let case:serde_json::Value=serde_json::from_str(include_str!("../🎟️controlled/📐️.json")).unwrap();let name=case["input"][0][0].as_str().unwrap();let number=case["input"][0][1].as_u64().unwrap();let mut callback=|_|true;let mut control=crate::NativeDecodeControl::new(bank.maximum_capacity_bytes,&mut callback);let key=SharedOwner::admit(String::from(name),RetainedCloneGrant{maximum_items:1,..bank}, &mut None);let work=key.work;let(key,p)=key.result.map_err(|(e,_)|e).unwrap();post(&mut bank,&mut fuel,p,work);let value=SharedOwner::admit(number,RetainedCloneGrant{maximum_items:1,..bank}, &mut None);let work=value.work;let(value,p)=value.result.map_err(|(e,_)|e).unwrap();post(&mut bank,&mut fuel,p,work);let base=OrderedMap::new();let mut cursor=base.begin_set_shared(key,value);let mut moved=false;for _ in 0..law["maximumTurns"].as_u64().unwrap(){if cursor.is_complete(){break}let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||cursor.advance_insert_controlled(RetainedCloneGrant{maximum_items:1,..bank},&mut control));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(&mut bank,&mut fuel,p,turn.work);moved|=cursor.state.value.is_none();}assert!(moved);assert!(cursor.is_complete());let output=cursor.take_result().unwrap();assert_eq!(serde_json::to_value(output.get(name).copied()).unwrap(),case["output"]);cursor.begin_close();close(cursor,&mut bank,&mut fuel);close(base,&mut bank,&mut fuel);close(output,&mut bank,&mut fuel);}
